        'profile.docsret_forever':  'dauerhaft',
        'profile.docsret_removed':  '{n} Dateien entfernt',
        'profile.docsret_hint':     'Erzeugte Dateien (Präsentationen, Tabellen, PDFs, Bilder) liegen auf dem Server und sind über den Download-Link im Chat erreichbar. Dieser Link verfällt nicht von selbst – das Löschen der Datei ist der einzige Widerruf. Nach Ablauf der Frist werden die Dateien beim täglichen Lauf entfernt; der Chat-Verlauf bleibt erhalten, nur der Download funktioniert dann nicht mehr. Erlaubt sind 15 bis 90 Tage. Mit „dauerhaft“ wird nie automatisch gelöscht – das bedeutet, dass auch Dateien mit vertraulichem Inhalt unbegrenzt abrufbar bleiben.',
        'profile.maxtok_hint':      'Dieser Wert begrenzt, wie viele Token ein Modell in einer einzelnen Antwort erzeugen darf. Er ist vor allem bei Reasoning-Modellen wichtig: ohne Obergrenze kann ein Modell einen sehr langen Gedankengang produzieren und dabei das Antwort-Timeout reißen, sodass die Anfrage komplett verloren geht. Ist der Wert zu klein gewählt, wird die Antwort mitten im Satz abgeschnitten – ein typisches Anzeichen sind Antworten, die ohne Punkt enden. Bei hoher Denktiefe zählen Denk- und Antworttoken gemeinsam gegen dieses Limit, hier sind 16000 oder mehr sinnvoll. Erlaubt sind 256 bis 131072 Token; der Wert gilt global für alle Profile und wirkt bei OpenAI-kompatiblen Anbietern sowie bei Anthropic.',
        'profile.section_ctxthr':   'Kontext-Komprimierung',
        'profile.ctxthr_label':     'Schwellwert (Gesprächseinträge)',
        'profile.ctxthr_hint':      'Ab wie vielen Gesprächseinträgen der Verlauf eines Chats automatisch zusammengefasst wird, damit er in das Kontextfenster des Modells passt. Ein Eintrag ist eine Frage, eine Antwort oder ein Werkzeug-Ergebnis. Kleinere Werte sparen Token und Kosten, verlieren aber früher Details aus dem Gesprächsanfang; größere Werte behalten mehr, machen jede Anfrage aber teurer und langsamer. Erlaubt sind 4 bis 200 Einträge, Standard ist 30. Der Wert gilt global für alle Benutzer und alle Sitzungen; den aktuellen Füllstand einer Sitzung zeigt die Kontext-Anzeige im Chat.',
        'profile.temp_label':       'Temperature (Kreativität)',
        'profile.temp_ph':          'leer = auto (Anbieter entscheidet)',
        'profile.temp_hint':        'Die Temperature steuert, wie stark das Modell vom wahrscheinlichsten nächsten Wort abweicht: niedrige Werte liefern sachliche und gut reproduzierbare Antworten, hohe Werte mehr Abwechslung und Kreativität. Der Standard ist „auto“ – der Parameter wird dann gar nicht mitgesendet und der Anbieter entscheidet selbst; das ist nötig für aktuelle Claude-Modelle, die Temperature-Angaben mit einem Fehler ablehnen. Achtung: der Anbieter-Standard liegt bei vielen OpenAI-kompatiblen Servern und bei Gemini deutlich über 0.2, und ab etwa 0.7 zerfallen die JSON-Argumente von Werkzeugaufrufen zunehmend. Wer verlässliche Tool-Aufrufe braucht, trägt deshalb eine feste Zahl ein – 0.2 entspricht dem Verhalten vor Juli 2026. Erlaubt sind Werte von 0.0 bis 2.0; für reine Text- und Schreibaufgaben ohne Tools sind 0.7 bis 1.0 ein guter Ausgangspunkt.',
        // ── Spezialisierte Rollen-Agenten (backend/agent_roles.py) ──
        'roles.section':            'Spezialisierte Agenten (Rollen)',
        'roles.hint':               'Eine Rolle ist ein Agent mit eigenem Auftrag, eigenem Werkzeugsatz und optional eigenem LLM-Profil. Der Hauptagent erkennt anhand der Beschreibung, welche Rolle für eine Teilaufgabe zuständig ist, übergibt sie, wartet auf das Ergebnis und arbeitet damit weiter. Eine Rolle kann nie mehr als der Benutzer, der sie beauftragt – ihr Werkzeugsatz wird mit dessen Rechten geschnitten. Ohne eingerichtete Rolle verhält sich der Agent wie bisher.',
        'roles.new':                '+ Rolle anlegen',
