        'license.confirm_clear':    'Lizenzschlüssel entfernen? Das System läuft danach mit den FREE-Grenzen: keine Software-Updates, ein LLM-Profil, fünf aktive Skills, fünf Benutzer und 50 Dateien in der Wissensdatenbank.',
        'license.hint':             'Der Lizenzschlüssel wird vom Anbieter ausgestellt und ist an dieses System gebunden. Damit die gekaufte Stufe wirksam wird, muss die oben angezeigte Hardware-Kennung beim Anbieter hinterlegt sein – bis dahin läuft das System als FREE. Der Status (Gültigkeit, Widerruf, Stufenänderung) wird täglich beim Anbieter geprüft; ist der Prüfdienst vorübergehend nicht erreichbar, gilt der zuletzt bekannte Stand noch 14 Tage weiter. Ohne gültige Lizenz gelten die FREE-Grenzen: keine Software-Updates, ein LLM-Profil, fünf aktive Skills, fünf Benutzer und 50 Dateien in der Wissensdatenbank.',

        // ── Security Form Labels ──────────────────────────────
        'security.section_pw':      'Kennwort ändern',
        'security.section_ad':      'Berechtigungen (lokal und Active Directory / LDAP)',
        'security.section_2fa':     'Zwei-Faktor-Authentifizierung (2FA)',
        'security.section_status':  'Sicherheitsstatus',
        'security.section_incidents':   'Angriffsprävention und Sicherheitsvorfälle',
        'security.doc_btn_title':       'Technische Funktionsbeschreibung der Sicherheitsschicht',
        'security.doc_btn_label':       'Funktionsweise & Sicherheitsfeatures',
        'security.incidents_desc':      'Erkennt Jailbreak- und Prompt-Injection-Versuche in Chat, Support und WhatsApp. Betroffene Konten werden sofort gesperrt – sie können sich noch anmelden und sehen dort nur den Sperr-Hinweis samt Protokoll. Administratoren können sperren und wieder freischalten – auch über das Menü unter „Angemeldete Benutzer“ im Portal.',
        'security.guard_enabled':       'Sicherheitsschicht aktiv',
        'security.guard_enabled_desc':  'Master-Schalter. Ist die Schicht aus, werden keine Eingaben geprüft und keine Konten gesperrt.',
        'security.guard_heuristic':     'Muster-Erkennung (Heuristik)',
        'security.guard_heuristic_desc':'Schnelle, lokale Prüfung gegen bekannte Jailbreak-/Injection-Signaturen (z. B. „ignore all previous instructions"). Kostenlos und sofort; im Protokoll ist nachvollziehbar, welches Muster ausgelöst hat.',
        'security.guard_llm':           'LLM-Klassifikator',
        'security.guard_llm_desc':      'Zusätzliche Bewertung per LLM. Sind beide Optionen aktiv (Hybrid), bestätigt das LLM jeden Heuristik-Verdacht, bevor gesperrt wird (weniger Fehlalarme). Nur LLM aktiv: jede Eingabe wird klassifiziert (robuster, aber Kosten/Latenz je Nachricht).',
        'security.blocked_accounts':    'Gesperrte Konten',
        'security.section_sandbox':     'Systemschutz / Sandbox (Netzwerk-Benutzer)',
        'security.sandbox_desc':        'Für Netzwerk-/Domain-Benutzer ist der Datei- und Shell-Zugriff im Code beschränkt (Schreiben nur im Arbeitsbereich, Lesen nur in Wissens-/Arbeitsverzeichnissen; Secrets, Root- und System-Bereiche gesperrt; verschleierte/base64-kodierte Ausführung blockiert). Ist die OS-Sandbox aktiv, laufen deren Shell-Befehle zusätzlich als unprivilegierter Betriebssystem-Benutzer.',
        'security.sandbox_on':          'OS-Sandbox aktiv',
        'security.sandbox_off':         'OS-Sandbox inaktiv – nur Code-Härtung aktiv',
        'security.sandbox_missing':     'Sandbox konfiguriert, aber OS-Benutzer fehlt',
        'security.sandbox_user':        'Sandbox-Benutzer',
        'security.section_broker':      'Root-Freigaben (Root-Broker)',
        // ── Erinnerungs-Freigaben (Messenger) ──
        'security.section_reminders':   'Erinnerungen per Messenger',
        'security.reminders_desc':      'Zeitgesteuerte Aufträge darf nur ein Administrator anlegen – sonst könnte sich ein Netzwerk-Benutzer (oder eine untergeschobene Nachricht) einen Agenten einrichten, der außerhalb jeder Sitzung dauerhaft läuft. Hier freigegebene Absender dürfen sich trotzdem EINMALIGE Erinnerungen an sich selbst setzen: zur Fälligkeit wird nur diese Nachricht verschickt, es läuft keine Aufgabe und kein Werkzeug. Eine Zeile pro Absender – WhatsApp als Telefonnummer (+491701234567), Telegram als tg:123456789.',
        'security.reminders_save':      'Freigaben speichern',
