        'security.broker_desc':         'Im getrennten Betrieb läuft die Benutzeroberfläche unprivilegiert; alles, was root braucht, läuft über den Root-Broker. Jede Root-Operation erscheint hier als auditierbarer Eintrag: Systemoperationen werden automatisch erlaubt (widerrufbar), unbekannte Root-Shell-Befehle des Agenten warten auf deine Freigabe. Entscheidungen wirken sofort.',
