        'security.broker_setup_confirm':'Getrennten Betrieb jetzt aktivieren/reparieren?\n\nDas Backend wird auf einen unprivilegierten Dienst-Benutzer umgestellt, Root-Operationen laufen danach über den Root-Broker. jarvis.service und jarvis-broker.service starten dabei NEU – die Oberfläche ist für einige Sekunden nicht erreichbar.',
        'security.broker_teardown_confirm':'Wirklich in den Alt-Betrieb zurückschalten?\n\nDas Backend läuft danach wieder MIT root-Rechten (keine Prozess-Trennung); der Broker-Dienst wird deaktiviert. Freigabeliste + Audit bleiben aktiv. jarvis.service startet dabei NEU – die Oberfläche ist kurz nicht erreichbar.',
