        'security.knowledge_editors_intro': 'Diese Liste steuert den GLOBALEN Zugriff auf die gesamte Wissens-Verwaltung (diese Seite, Ordner, Extraktor, Import/Export, Gruppen anlegen/löschen). Globale Editoren müssen EXPLIZIT eingetragen werden: leer = niemand ist globaler Editor – ausdrücklich auch keine lokalen Admins. Soll jemand bearbeiten dürfen, muss er hier stehen; für „alle" trägst du die AD-Gruppe „Jeder"/Domänen-Benutzer als Editor-Gruppe ein. Gezielten Schreibzugriff auf einzelne Gruppen (für Domänennutzer) vergibst du separat unter „Wissen → jeweilige Gruppe → 🔐".',
