        // ── Security – AD / 2FA ───────────────────────────────────────────────
        'security.pw_change_hint':  'Ändert das Linux-Benutzerkonto <code>jarvis</code> – gilt für die Web-Oberfläche und SSH-Login. <strong>Nicht</strong> das WebDAV-Passwort.',
