        'chat.greeting_sub':    'Wie kann ich dir helfen?',
        // Willkommens-Chat "Beispiel Prompts" (Sitzung wird pro Benutzer einmalig
        // angelegt, siehe backend/chat_sessions.py::ensure_welcome_session).
        // Jedes Beispiel hat _label (Kachel-Titel), _desc (Untertitel) und _prompt
        // (der Text, der beim Klick gesendet wird).
        'chat.welcome_head':    'Willkommen! Ich bin mehr als ein Chat.',
        'chat.welcome_intro':   'Ich kann Dokumente erstellen, Daten auswerten, im Web und in deiner Wissensdatenbank recherchieren, Bilder erzeugen, Aufträge zeitgesteuert wiederholen und für größere Vorhaben mehrere Agenten parallel arbeiten lassen. Hier sind Beispiele – klicke eines an, um es sofort auszuprobieren:',
        'chat.welcome_hint':    'Ein Klick sendet das Beispiel als Nachricht. Du kannst jeden Prompt danach frei abwandeln – und den Verlauf „Beispiel Prompts“ jederzeit löschen.',
        'chat.wex_excel_label':  'Excel mit Diagramm',
        'chat.wex_excel_desc':   'Tabelle bauen und daraus ein Chart rendern',
        'chat.wex_excel_prompt': 'Erstelle eine Excel-Tabelle mit den Monatsumsätzen 2026 für die Regionen Nord, Süd und West (nutze plausible Beispielzahlen), berechne Summen und Mittelwerte je Region und erzeuge zusätzlich ein Balkendiagramm der Jahresumsätze als Bild.',
        'chat.wex_word_label':   'Word-Angebot als PDF',
        'chat.wex_word_desc':    'Dokument schreiben und exportieren',
        'chat.wex_word_prompt':  'Schreibe ein Word-Dokument: ein Angebot über ein IT-Projekt mit 15 Personentagen – mit Deckblatt, Leistungsbeschreibung in Abschnitten, Kostentabelle und Zahlungsbedingungen. Exportiere das Ergebnis anschließend als PDF.',
        'chat.wex_ppt_label':    'Präsentation mit Schaubild',
        'chat.wex_ppt_desc':     'PowerPoint inkl. Kästen und Pfeilen',
        'chat.wex_ppt_prompt':   'Erstelle eine PowerPoint-Präsentation mit 6 Folien über die Vorteile von Prozessautomatisierung. Baue auf einer Folie ein echtes Schaubild mit Kästen und Verbindungspfeilen (kein Aufzählungstext) für den Ablauf: Auslöser → Prüfung → Verarbeitung → Benachrichtigung.',
        'chat.wex_data_label':   'Angehängte Datei auswerten',
        'chat.wex_data_desc':    'Erst 📎 anhängen, dann senden',
        'chat.wex_data_prompt':  'Analysiere die angehängte Tabelle: nenne die drei auffälligsten Entwicklungen, prüfe die Daten auf Lücken und Ausreißer und stelle das Wichtigste als Liniendiagramm dar.',
        'chat.wex_kb_label':     'Wissensdatenbank befragen',
        'chat.wex_kb_desc':      'Antwort aus internen Dokumenten',
        'chat.wex_kb_prompt':    'Durchsuche unsere Wissensdatenbank nach Informationen zum Thema Urlaubsantrag und fasse die wichtigsten Punkte zusammen. Gib zu jeder Aussage an, aus welchem Dokument sie stammt, und sage klar, wenn etwas dort nicht steht.',
        'chat.wex_jira_label':   'Tickets auswerten',
        'chat.wex_jira_desc':    'Überblick über offene Vorgänge',
        'chat.wex_jira_prompt':  'Verschaffe mir einen Überblick über die offenen Tickets der letzten 14 Tage: gruppiere sie nach Priorität, nenne je Gruppe die Anzahl und liste die fünf ältesten mit Ticketnummer, Kurzbeschreibung und Alter in Tagen auf. Stelle die Verteilung zusätzlich als Diagramm dar.',
        'chat.wex_conf_label':   'Confluence durchsuchen',
        'chat.wex_conf_desc':    'Dokumentation finden und zusammenfassen',
        'chat.wex_conf_prompt':  'Durchsuche Confluence nach Anleitungen zum Thema Installation und fasse die wichtigsten Schritte in der richtigen Reihenfolge zusammen. Nenne zu jedem Punkt den Seitentitel als Quelle und sage ausdrücklich, wenn ein Schritt dort nicht dokumentiert ist.',
        'chat.wex_ibs_label':    'Kundenvorgänge finden',
        'chat.wex_ibs_desc':     'Ereignisse nach Schlagworten durchsuchen',
        'chat.wex_ibs_prompt':   'Suche in der Kundenverwaltung nach Vorgängen zu den Schlagworten „Drucker" und „Ausdruck". Fasse die wiederkehrenden Themen zusammen, nenne zu jedem Punkt Vorgangsnummer und Datum und sage mir, ob sich daraus ein Muster erkennen lässt.',
        'chat.wex_multi2_label': 'Alle Quellen auf einmal',
        'chat.wex_multi2_desc':  'Wissensdatenbank, Confluence und Tickets zusammenführen',
        'chat.wex_multi2_prompt': 'Beantworte diese Frage aus allen verfügbaren Quellen: Wie läuft das Melden und Bearbeiten einer Störung bei uns ab? Ziehe Wissensdatenbank, Confluence und vergleichbare Tickets heran, führe die Ergebnisse zu einem Ablauf zusammen, benenne Widersprüche zwischen den Quellen offen und gib zu jeder Aussage die Quelle an.',
        'chat.wex_code_label':   'Skript schreiben',
        'chat.wex_code_desc':    'Fertiger Code mit Erklärung',
        'chat.wex_code_prompt':  'Schreibe ein Python-Skript, das alle PDF-Dateien in einem Ordner in Textdateien umwandelt, dabei Fehler pro Datei abfängt und am Ende eine Übersicht ausgibt. Zeige den vollständigen Code im Chat und erkläre den Aufruf.',
