        'branding.pptx_heading':      'PowerPoint template',
        'branding.pptx_hint':         'The agent builds presentations from a template: 16:9, real slide masters, colours and font from your branding. Without your own template one is generated automatically from the brand colour. Upload a real corporate template here to replace it – layouts, colours and placeholders then come from that file.',
        'branding.pptx_upload':       'Upload template (.pptx or .potx)',
