        'profile.section_tts':      'Text-to-Speech (TTS)',
        'profile.section_timeout':  'Response Timeout',
        'profile.timeout_label':    'Timeout for LLM requests (seconds)',
        'profile.timeout_hint':     'How long to wait for the model\'s response before aborting. Slow local models need higher values (10–1800 s). Applies globally to all profiles.',
        'profile.save_btn':         'Save',
        // ── Response length (global) + temperature (per profile) ──
        'profile.section_maxtok':   'Maximum response length',
        'profile.maxtok_label':     'Response cap (tokens)',
        'profile.section_docsret':  'Retention of generated documents',
        'profile.docsret_label':    'Keep files for (days)',
        'profile.docsret_forever':  'keep forever',
        'profile.docsret_removed':  '{n} files removed',
        'profile.docsret_hint':     'Generated files (presentations, spreadsheets, PDFs, images) are stored on the server and reachable through the download link in the chat. That link never expires on its own – deleting the file is the only way to revoke it. Once the retention period passes, the files are removed by the daily sweep; the chat history stays, only the download stops working. The allowed range is 15 to 90 days. With "keep forever" nothing is ever deleted automatically – which means files with confidential content stay retrievable indefinitely.',
        'profile.maxtok_hint':      'This value caps how many tokens a model may generate in a single response. It matters most with reasoning models: without a cap, a model can produce a very long chain of thought and blow past the response timeout, losing the request entirely. Set it too low and the answer is cut off mid-sentence – responses ending without a full stop are the usual tell. At high reasoning depth, thinking and answer tokens both count against this limit, so 16000 or more is sensible there. The allowed range is 256 to 131072 tokens; the value applies globally to all profiles and takes effect for OpenAI-compatible providers as well as Anthropic.',
        'profile.section_ctxthr':   'Context compression',
        'profile.ctxthr_label':     'Threshold (conversation entries)',
        'profile.ctxthr_hint':      'How many conversation entries a chat may hold before its history is summarised automatically so it still fits the model context window. An entry is a question, an answer or a tool result. Lower values save tokens and cost but lose detail from the start of the conversation earlier; higher values keep more but make every request slower and more expensive. The allowed range is 4 to 200 entries, the default is 30. The value applies globally to all users and sessions; the current fill level of a session is shown by the context indicator in the chat.',
        'profile.temp_label':       'Temperature (creativity)',
        'profile.temp_ph':          'empty = auto (provider decides)',
        'profile.temp_hint':        'Temperature controls how far the model strays from the most likely next word: low values give factual, reproducible answers, high values more variety and creativity. The default is \'auto\', which omits the parameter entirely and lets the provider decide; this is required for current Claude models, which reject temperature settings with an error. Careful: the provider default is well above 0.2 on many OpenAI-compatible servers and on Gemini, and from roughly 0.7 upwards the JSON arguments of tool calls degrade. If you need reliable tool calls, enter a fixed number instead – 0.2 matches the behaviour before July 2026. The allowed range is 0.0 to 2.0; for pure writing tasks without tools, 0.7 to 1.0 is a good starting point.',
        // ── Specialised role agents (backend/agent_roles.py) ──
        'roles.section':            'Specialised agents (roles)',
        'roles.hint':               'A role is an agent with its own brief, its own tool set and optionally its own LLM profile. The main agent uses the description to decide which role is responsible for a sub-task, hands it over, waits for the result and continues with it. A role can never do more than the user who commissioned it – its tool set is intersected with that user\u2019s permissions. With no role configured the agent behaves exactly as before.',
        'roles.new':                '+ Add role',
        'roles.disable':            'Disable role',
        'roles.enable':             'Enable role',
