        'security.section_incidents':   'Attack prevention & security incidents',
        'security.doc_btn_title':       'Technical function description of the security layer',
        'security.doc_btn_label':       'How it works & security features',
        'security.incidents_desc':      'Detects jailbreak and prompt-injection attempts in chat, support and WhatsApp. Affected accounts are locked immediately – they may still sign in but only see the lock notice and the activity log. Administrators can block and restore access – also from the “Signed-in users” menu in the portal.',
        'security.guard_enabled':       'Security layer active',
        'security.guard_enabled_desc':  'Master switch. When off, no input is inspected and no accounts are locked.',
        'security.guard_heuristic':     'Pattern detection (heuristic)',
        'security.guard_heuristic_desc':'Fast local check against known jailbreak/injection signatures (e.g. "ignore all previous instructions"). Free and instant; the log shows which pattern triggered.',
        'security.guard_llm':           'LLM classifier',
        'security.guard_llm_desc':      'Additional assessment via LLM. With both options on (hybrid) the LLM confirms every heuristic suspicion before locking (fewer false positives). LLM only: every input is classified (more robust, but cost/latency per message).',
        'security.blocked_accounts':    'Locked accounts',
        'security.section_sandbox':     'System protection / sandbox (network users)',
        'security.sandbox_desc':        'For network/domain users, file and shell access is restricted in code (writes only in the workspace, reads only in knowledge/work directories; secrets, root and system areas blocked; obfuscated/base64-encoded execution blocked). When the OS sandbox is active, their shell commands additionally run as an unprivileged operating-system user.',
