        'security.section_reminders':   'Reminders via messenger',
        'security.reminders_desc':      'Only an administrator may create scheduled jobs – otherwise a network user (or an injected message) could set up an agent that keeps running outside any session. Senders approved here may still set ONE-TIME reminders to themselves: when due, only that message is sent, no task and no tool runs. One entry per line – WhatsApp as a phone number (+491701234567), Telegram as tg:123456789.',
