        'security.knowledge_editors_intro': 'This list controls GLOBAL access to the entire knowledge administration (this page, folders, extractor, import/export, creating/deleting groups). Global editors must be entered EXPLICITLY: empty = nobody is a global editor – explicitly not even local admins. Whoever should be able to edit must be listed here; for "everyone" add the AD group "Everyone"/Domain Users as the editor group. Scoped write access to individual groups (for domain users) is granted separately under "Knowledge → the group → 🔐".',
