        'security.unattended_desc':     'Applies Debian security patches automatically (unattended-upgrades). Deliberately narrow: security source only – no general version jumps underneath the running service, no automatic reboot and no automatic package cleanup (the latter would remove the agent\u2019s dependencies, e.g. cmake/boost for face recognition, ffmpeg for speech or LibreOffice parts). The daily package index refresh stays on when you switch this off – a stale index makes package installs fail with "404 Not Found".',
