        // Welcome chat "Beispiel Prompts" – see backend/chat_sessions.py
        'chat.welcome_head':    'Welcome! I am more than a chat.',
        'chat.welcome_intro':   'I can create documents, analyse data, research the web and your knowledge base, generate images, repeat jobs on a schedule and — for bigger tasks — run several agents in parallel. Here are some examples; click one to try it right away:',
        'chat.welcome_hint':    'A click sends the example as a message. Feel free to adapt any prompt afterwards – and you can delete the “Beispiel Prompts” chat at any time.',
        'chat.wex_excel_label':  'Excel with a chart',
        'chat.wex_excel_desc':   'Build a sheet and render a chart from it',
        'chat.wex_excel_prompt': 'Create an Excel sheet with the 2026 monthly revenue for the regions North, South and West (use plausible sample figures), calculate totals and averages per region, and additionally render a bar chart of the yearly revenue as an image.',
        'chat.wex_word_label':   'Word quote as PDF',
        'chat.wex_word_desc':    'Write a document and export it',
        'chat.wex_word_prompt':  'Write a Word document: a quote for an IT project of 15 person-days – with a cover page, a scope of work split into sections, a cost table and payment terms. Then export the result as a PDF.',
        'chat.wex_ppt_label':    'Deck with a diagram',
        'chat.wex_ppt_desc':     'PowerPoint including boxes and arrows',
        'chat.wex_ppt_prompt':   'Create a PowerPoint deck of 6 slides about the benefits of process automation. On one slide, build a real diagram with boxes and connecting arrows (not bullet text) for the flow: trigger → validation → processing → notification.',
        'chat.wex_data_label':   'Analyse an attached file',
        'chat.wex_data_desc':    'Attach 📎 first, then send',
        'chat.wex_data_prompt':  'Analyse the attached spreadsheet: name the three most notable developments, check the data for gaps and outliers, and visualise the key finding as a line chart.',
        'chat.wex_kb_label':     'Query the knowledge base',
        'chat.wex_kb_desc':      'Answers from internal documents',
        'chat.wex_kb_prompt':    'Search our knowledge base for information about requesting annual leave and summarise the key points. State for every claim which document it comes from, and say clearly if something is not covered there.',
        'chat.wex_jira_label':   'Analyse tickets',
        'chat.wex_jira_desc':    'Overview of open issues',
        'chat.wex_jira_prompt':  'Give me an overview of the tickets opened in the last 14 days: group them by priority, state the count per group and list the five oldest with ticket number, short description and age in days. Also render the distribution as a chart.',
        'chat.wex_conf_label':   'Search Confluence',
        'chat.wex_conf_desc':    'Find and summarise documentation',
        'chat.wex_conf_prompt':  'Search Confluence for guides on the topic of installation and summarise the key steps in the correct order. Name the page title as the source for each point, and say explicitly if a step is not documented there.',
        'chat.wex_ibs_label':    'Find customer events',
        'chat.wex_ibs_desc':     'Search events by keywords',
        'chat.wex_ibs_prompt':   'Search the customer management system for events matching the keywords "printer" and "printout". Summarise the recurring themes, give the event number and date for each point, and tell me whether a pattern emerges.',
        'chat.wex_multi2_label': 'All sources at once',
        'chat.wex_multi2_desc':  'Combine knowledge base, Confluence and tickets',
        'chat.wex_multi2_prompt': 'Answer this question from every available source: how do we report and process an incident? Draw on the knowledge base, Confluence and comparable tickets, merge the results into one process, state any contradictions between the sources openly, and cite the source for each statement.',
